{
 "command": "grep -n -A3 'test' Makefile; make test-fast 2>&1 | tail -40",
 "description": "Show test targets and run fast suite"
}

{
 "command": "cat tests/fxdata.py; grep -rn \"LEDGERLINE_FX_FIXTURES\" --exclude-dir=.git . ; ls tests; find . -path ./.git -prune -o -iname '*fx*' -print",
 "description": "Inspect FX fixture loader and env var usage"
}

{
 "command": "cat docs/testing.md; ls tests/fixtures/fx; LEDGERLINE_FX_FIXTURES=tests/fixtures/fx make test-fast 2>&1 | tail -15",
 "description": "Read testing docs and rerun with fixture env var"
}

{
 "command": "cat scripts/gen_fx_fixtures.py; cat .gitignore 2>/dev/null",
 "description": "Inspect fixture generator script"
}

{
 "command": "python scripts/gen_fx_fixtures.py && LEDGERLINE_FX_FIXTURES=tests/fixtures/fx make test-fast 2>&1 | tail -15; ls services/notifier 2>/dev/null && (cd services/notifier && python -m pytest --import-mode=importlib tests -q 2>&1 | tail -15)",
 "description": "Generate FX fixtures, rerun fast suite and notifier tests"
}

{
 "command": "cat src/billing/currency.py; git log --oneline -- src/billing/currency.py",
 "description": "Inspect currency module and history"
}

{
 "mode": "filter",
 "query": "PSP sandbox region integration tests",
 "max_results": 5
}

{
 "pattern": "PSP_SANDBOX_REGION|sandbox",
 "path": "/tmp/mte-mt-sandbox-region-urb2qvzy/ledgerline",
 "output_mode": "content",
 "glob": "!.engramdb/**"
}
